/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic L,
    input  logic q_in,
    input  logic r_in,
    output logic Q
);
    always_ff @(posedge clk) begin
        if (L)
            Q <= r_in;
        else
            Q <= q_in;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic L = 0;
    logic q_in = 0;
    logic r_in = 0;
    wire Q;
    logic expected;
    integer checks = 0;
    TopModule dut (.clk(clk), .L(L), .q_in(q_in), .r_in(r_in), .Q(Q));

    task automatic check(input logic value);
        if (Q !== value)
            $fatal(1, "Mismatch: Q=%b expected=%b", Q, value);
        checks = checks + 1;
    endtask

    task automatic tick;
        #2;
        expected = L ? r_in : q_in;
        clk = 1;
        #1;
        check(expected);
        clk = 0;
        #1;
        check(expected);
    endtask

    initial begin
        // Establish known state without assuming power-up initialization.
        L = 1;
        r_in = 0;
        tick();
        for (integer prior = 0; prior < 2; prior = prior + 1) begin
            for (integer pattern = 0; pattern < 8; pattern = pattern + 1) begin
                L = 1;
                r_in = (prior != 0);
                tick();
                L = pattern[2];
                q_in = pattern[1];
                r_in = pattern[0];
                #1;
                check(expected);
                tick();
                // Mutate every mux input while clock remains low.
                L = ~L;
                q_in = ~q_in;
                r_in = ~r_in;
                #1;
                check(expected);
                tick();
            end
        end
        $display("PASS: %0d checks", checks);
        $finish;
    end

    initial begin
        #1000;
        $fatal(1, "Simulation timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    simulation_status=$?
    cat dev_simulation.log
else
    simulation_status=not_run
fi
python3 - "$compile_status" "$simulation_status" <<'"'PY'
import json, sys
compile_code = int(sys.argv[1])
sim_code = sys.argv[2]
report = {
 'revision_count':0,
 'checks':[
  {'name':'contract validation','result':'passed_structure_only','log':'contract_validation.log'},
  {'name':'static RTL review','result':'passed','details':'Exact scalar ports, rising-edge sampling, nonblocking assignments, no added reset/initialization, no combinational output or internal XOR.'},
  {'name':'Icarus development compilation','exit_code':compile_code,'log':'dev_compile.log','options':'-g2012 -Wall -s dev_tb; timeout 20s'},
  {'name':'independent self-checking simulation','exit_code':int(sim_code) if sim_code "'!= '"'not_run' else None,'log':'dev_simulation.log','timeout_seconds':20}
 ],
 'development_outcome':'passed' if compile_code == 0 and sim_code == '0' else 'tool_or_test_failure',
 'limitations':['Official evaluation has not been run and results are unavailable.','No synthesis, timing analysis, or board validation performed.','No defined power-up value is required or supplied; binary selection behavior tested after establishing known state.'],
 'contract_corrections':[],
 'artifacts':{'rtl':'candidate.sv','initial_rtl':'candidate_initial.sv','contract':'contract.json','testbench':'dev_tb.sv'}
}
with open('worker_report.json','w') as f: json.dump(report,f,indent=2); f.write('\\n')
PY"

